                if (count >= Math.Max(2, settings.MinCycles))
                {
                    // A pause to look around and bstep again is the same bstep.
                    if (
                        runs.Count > 0
                        && cycles[first].Seconds - End(runs[^1]) <= settings.MergeSeconds
                    )
